24. 다음 C 코드에 해당하는 문자열 탐색 방법은? (단, s1은 입력 문자열,
s2는 s1에서 찾고자 하는 패턴 문자열이고, n1은 s1의 길이, n2는
s2의 길이를 나타낸다)
int match(char *s1, char *s2) {
int pt = 0, p = 0;
while(pt != n1 && p != n2) {
if (s1[pt] == s2[p]) {
pt++;
p++;
} else {
pt = pt - p + 1;
p = 0;
}
}
if (p == n2) return pt-p;
else return -1;
}
